    def normalize_filename(filename):
        # Normalize filename to ASCII
        return ''.join(c for c in unicodedata.normalize('NFKD', filename).encode('ascii', 'ignore') if ord(c) < 128)

    def get_file_info(file_path):
        # Get file size and MD5 hash
        file_size = os.path.getsize(file_path)
        with open(file_path, 'rb') as f:
            file_hash = md5(f.read()).hexdigest()
        return {'Size': file_size, 'MD5 Hash': file_hash}

    def process_directory(directory):
        result_dict = {}
        for root, _, files in os.walk(directory):
            for file_name in files:
                normalized_name = normalize_filename(file_name)
                full_path = os.path.join(root, file_name)
                info = get_file_info(full_path)
                result_dict[normalized_name] = info
        return result_dict

