def task_func(source_directory: str, target_directory: str, pattern: str = r"\d{4}") -> int:
    if not os.path.isdir(source_directory):
        return 0

    for root, _, files in os.walk(source_directory):
        for file in files:
            match = re.match(pattern, file)
            if match:
                src_file = os.path.join(root, file)
                dst_file = os.path.join(target_directory, match.group())
                try:
                    shutil.move(src_file, dst_file)
                except Exception as e:
                    print(f"Error moving {src_file}: {e}")
                    continue
                else:
                    print(f"Moved {file} to {dst_file}")

    return len(os.listdir(target_directory))

